def flatten(x,p=''):
 if isinstance(x,dict):
  for k,v in x.items():yield from flatten(v,p+'/'+str(k))
 elif isinstance(x,list):
  for i,v in enumerate(x):yield from flatten(v,p+'/'+str(i))
 else:yield p,x
